using sv_eef36a831ac74e0eb9d2fc80492fe591.Services;
using Microsoft.AspNetCore.Components;

namespace sv_eef36a831ac74e0eb9d2fc80492fe591.Components.Pages;

public partial class Settings
{
    private readonly string[] _sections = { "Profile", "Notifications", "Security", "Appearance" };
    private string _activeSection = "Profile";

    // Profile state
    private ProfileModel _editProfile = new();
    private UserProfile? _savedProfile;
    private string? _profileMessage;

    // Notifications state
    private NotificationsModel _editNotifications = new();
    private string? _notificationsMessage;
    private readonly List<string> _availableChannels = new() { "General", "Updates", "Marketing", "Engineering", "Support" };

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _changePasswordExpanded;
    private string _currentPassword = string.Empty;
    private string _newPassword = string.Empty;
    private string _confirmPassword = string.Empty;
    private string? _securityMessage;
    private bool _securityMessageIsError;
    private ActiveSession? _sessionToRevoke;
    private string _currentSessionId = string.Empty;

    // Appearance state
    private AppearanceModel _editAppearance = new();
    private string? _appearanceMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
        await LoadNotifications();
        await LoadSecurity();
        await LoadAppearance();
    }

    private void SetActiveSection(string section)
    {
        _activeSection = section;
        ClearMessages();
    }

    private void ClearMessages()
    {
        _profileMessage = null;
        _notificationsMessage = null;
        _securityMessage = null;
        _appearanceMessage = null;
    }

    // --- Profile ---
    private async Task LoadProfile()
    {
        _savedProfile = await SettingsService.GetProfileAsync();
        MapProfileToEdit(_savedProfile);
    }

    private void MapProfileToEdit(UserProfile profile)
    {
        _editProfile.DisplayName = profile.DisplayName;
        _editProfile.Email = profile.Email;
        _editProfile.AvatarUrl = profile.AvatarUrl;
        _editProfile.Bio = profile.Bio;
    }

    private async Task SaveProfile()
    {
        var profile = new UserProfile(_editProfile.DisplayName, _editProfile.Email, _editProfile.AvatarUrl, _editProfile.Bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        _profileMessage = "Profile saved successfully!";
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            MapProfileToEdit(_savedProfile);
        }
        _profileMessage = null;
    }

    // --- Notifications ---
    private async Task LoadNotifications()
    {
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _editNotifications.EmailNotifications = prefs.EmailNotifications;
        _editNotifications.PushNotifications = prefs.PushNotifications;
        _editNotifications.WeeklyDigest = prefs.WeeklyDigest;
        _editNotifications.MutedChannels = new List<string>(prefs.MutedChannels);
    }

    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted && !_editNotifications.MutedChannels.Contains(channel))
        {
            _editNotifications.MutedChannels.Add(channel);
        }
        else if (!isMuted)
        {
            _editNotifications.MutedChannels.Remove(channel);
        }
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(
            _editNotifications.EmailNotifications,
            _editNotifications.PushNotifications,
            _editNotifications.WeeklyDigest,
            new List<string>(_editNotifications.MutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationsMessage = "Notification preferences saved!";
    }

    // --- Security ---
    private async Task LoadSecurity()
    {
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        if (_securitySettings.Sessions.Count > 0)
        {
            _currentSessionId = _securitySettings.Sessions[0].Id;
        }
    }

    private async Task UpdatePassword()
    {
        _securityMessage = null;
        _securityMessageIsError = false;

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _securityMessage = "Please fill in all password fields.";
            _securityMessageIsError = true;
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _securityMessage = "New password and confirmation do not match.";
            _securityMessageIsError = true;
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = string.Empty;
        _newPassword = string.Empty;
        _confirmPassword = string.Empty;
        _securityMessage = "Password updated successfully!";
    }

    private void PromptRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private async Task ConfirmRevokeSession()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            await LoadSecurity();
            _sessionToRevoke = null;
            _securityMessage = "Session revoked.";
            _securityMessageIsError = false;
        }
    }

    private void CancelRevokeSession()
    {
        _sessionToRevoke = null;
    }

    // --- Appearance ---
    private async Task LoadAppearance()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _editAppearance.Theme = settings.Theme;
        _editAppearance.FontSize = settings.FontSize;
        _editAppearance.Language = settings.Language;
        _editAppearance.CompactMode = settings.CompactMode;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{_editAppearance.Theme.ToLowerInvariant()}");
        classes.Add($"preview-font-{_editAppearance.FontSize.ToLowerInvariant()}");
        if (_editAppearance.CompactMode)
        {
            classes.Add("preview-compact");
        }
        return string.Join(" ", classes);
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_editAppearance.Theme, _editAppearance.FontSize, _editAppearance.Language, _editAppearance.CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _appearanceMessage = "Appearance settings saved!";
    }

    // Mutable view-models for binding
    private class ProfileModel
    {
        public string DisplayName { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string AvatarUrl { get; set; } = string.Empty;
        public string Bio { get; set; } = string.Empty;
    }

    private class NotificationsModel
    {
        public bool EmailNotifications { get; set; }
