    {
        _securityMessage = null;
        _securityMessageIsError = false;

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _securityMessage = "Please fill in all password fields.";
            _securityMessageIsError = true;
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _securityMessage = "New password and confirmation do not match.";
            _securityMessageIsError = true;
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = string.Empty;
        _newPassword = string.Empty;
        _confirmPassword = string.Empty;
        _securityMessage = "Password updated successfully!";
    }

